#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""NOVA Planner one-file project generator. Run: python build_nova_project.py"""
from pathlib import Path
import base64, io, zipfile, sys

PROJECT_ZIP_B64 = r""""""

def main():
    # Create the output beside this script so the location is predictable.
    output_dir = Path(__file__).resolve().parent
    project_dir = output_dir / "NOVA_Planner_Android"
    zip_out = output_dir / "NOVA_Planner_GitHub_Ready.zip"
    try:
        data = base64.b64decode(PROJECT_ZIP_B64)
        with zipfile.ZipFile(io.BytesIO(data), "r") as archive:
            archive.extractall(output_dir)
        with zipfile.ZipFile(zip_out, "w", zipfile.ZIP_DEFLATED) as out:
            for item in project_dir.rglob("*"):
                if item.is_file():
                    out.write(item, item.relative_to(project_dir))
        print("\nپروژه NOVA آماده شد!")
        print(f"پوشه پروژه: {project_dir}")
        print(f"فایل ZIP برای GitHub: {zip_out}")
        print("\nمراحل بعدی:")
        print("1) در https://github.com/new یک Repository بساز.")
        print("2) محتویات پوشه پروژه، همراه پوشه مخفی .github را آپلود کن.")
        print("3) وارد تب Actions شو و Build NOVA Planner APK را اجرا کن.")
        print("4) Artifact با نام NOVA-Planner-debug-APK را دانلود کن.")
        print("5) ZIP خروجی را باز کن؛ فایل app-debug.apk داخل آن است.")
        print("\nساخت APK در سرور GitHub انجام می‌شود و Android SDK محلی لازم نیست.")
    except Exception as exc:
        print(f"خطا در آماده‌سازی پروژه: {exc}", file=sys.stderr)
        raise SystemExit(1)

if __name__ == "__main__":
    main()
